using System.Net.Http.Json;using FCG.Contracts.Payments;using FCG.Games.Application.Abstractions;namespace FCG.Games.Infrastructure.Http;public sealed class PaymentsClient(HttpClient http):IPaymentsClient{public async Task<(Guid,string,string?)> ProcessAsync(Guid p,int u,int g,decimal a){var response=await http.PostAsJsonAsync("api/payments",new ProcessPaymentRequest(p,u,g,a));response.EnsureSuccessStatusCode();var data=await response.Content.ReadFromJsonAsync<ProcessPaymentResponse>()??throw new InvalidOperationException("Resposta inválida do serviço de pagamentos.");return(data.PaymentId,data.Status,data.FailureReason);}}
